/** Checklist item text → submission lookup key (mirrors New Hire Onboarding). */
const checklistKeyOf = (text: string) => text.trim().toLowerCase();

/** Requirements checklist card — the New Hire Onboarding right-side card,
 *  moved into the applicant View profile for Offer / Hired applicants only.
 *  Progress and submitted documents sync live with the onboarding record. */
function RequirementsChecklistCard({
  a,
  linkedHire,
  items,
  submissions,
  done,
  progress,
}: {
  a: Applicant;
  linkedHire: NewHire | null;
  items: { item: string; done: boolean }[];
  submissions: Record<
    string,
    { fileName?: string; fileUrl?: string; notes?: string; submittedAt?: string }
  >;
  done: number;
  progress: number;
}) {
  return (
    <Card className="flex h-full flex-col border-border/70">
      <CardContent className="flex min-h-0 flex-1 flex-col p-6">
        {/* Identity — mirrors the onboarding card header. */}
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="flex items-center gap-3">
            <Avatar className="h-12 w-12">
              <AvatarFallback
                className={cn(
                  "font-display",
                  progress === 100 ? "bg-success/15 text-success" : "bg-primary/10 text-primary",
                )}
              >
                {initials(a.name)}
              </AvatarFallback>
            </Avatar>
            <div>
              <h3 className="font-display text-xl font-semibold">{a.name}</h3>
              <p className="text-xs text-muted-foreground">{a.position}</p>
            </div>
          </div>
          <Badge
            variant="outline"
            className={cn(
              a.stage === "Hired"
                ? "border-success/40 bg-success/10 text-success"
                : "border-gold/40 bg-gold/10 text-gold-foreground",
            )}
          >
            {a.stage === "Hired" ? "Hired — onboarding filed" : "Offer extended"}
          </Badge>
        </div>

        <div className="mt-4 space-y-1 text-xs text-muted-foreground">
          <p>{a.email}</p>
          <p>{a.phone}</p>
          <p>Start date: {linkedHire ? linkedHire.startDate : "To be confirmed"}</p>
        </div>

        <div className="mt-4 flex min-h-[16rem] flex-1 flex-col">
          <div className="flex items-center justify-between text-xs">
            <span className="eyebrow">Requirements checklist</span>
            <span
              className={cn(
                "font-medium",
                progress === 100 ? "text-success" : "text-muted-foreground",
              )}
            >
              {progress}%
            </span>
          </div>
          <Progress
            value={progress}
            className="mt-2 h-2 [&>div]:bg-success [&>div]:transition-all"
          />

          <div className="mt-3 flex w-full items-center justify-between rounded-md border border-border/70 bg-muted/30 px-3 py-2 text-xs font-medium">
            <span>Checklist items ({items.length})</span>
            <span className="text-muted-foreground">
              {done}/{items.length}
            </span>
          </div>

          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain pr-1">
            {items.length === 0 ? (
